package incidents

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"time"
)

// Record kinds persisted in the durable incident log, one record per
// successfully committed creation or action.
const (
	RecordCreation = "create"
	RecordAction   = "action"
)

// StoredAction is one committed action with its server timestamp.
type StoredAction struct {
	Request Request
	At      time.Time
}

// Record is the unit of durable storage and of replay. Exactly one of
// Creation or Action is set, matching Kind.
type Record struct {
	Kind     string
	Creation *Creation
	Action   *StoredAction
	At       time.Time
}

// NewCreationRecord assembles the durable record for a creation.
func NewCreationRecord(creation Creation, at time.Time) Record {
	c := creation
	return Record{Kind: RecordCreation, Creation: &c, At: at}
}

// NewActionRecord assembles the durable record for an action.
func NewActionRecord(req Request, at time.Time) Record {
	a := StoredAction{Request: req, At: at}
	return Record{Kind: RecordAction, Action: &a, At: at}
}

// recordDTO is the JSON frame payload for one record. Timestamps use
// RFC3339Nano with a UTC location.
type recordDTO struct {
	Kind     string       `json:"kind"`
	At       time.Time    `json:"at"`
	Creation *creationDTO `json:"creation,omitempty"`
	Action   *actionDTO   `json:"action,omitempty"`
}

type creationDTO struct {
	ID       string `json:"id"`
	Title    string `json:"title"`
	Service  string `json:"service"`
	Operator string `json:"operator"`
}

type actionDTO struct {
	IncidentID      string `json:"incident_id"`
	ActionID        string `json:"action_id"`
	Operator        string `json:"operator"`
	ExpectedVersion int    `json:"expected_version"`
	Type            string `json:"type"`
	Content         string `json:"content"`
}

// MarshalRecord encodes one record as a strict JSON object.
func MarshalRecord(record Record) ([]byte, error) {
	dto := recordDTO{Kind: record.Kind, At: record.At.UTC()}
	switch record.Kind {
	case RecordCreation:
		if record.Creation == nil {
			return nil, fmt.Errorf("creation record is missing its content")
		}
		dto.Creation = &creationDTO{
			ID:       record.Creation.ID,
			Title:    record.Creation.Title,
			Service:  record.Creation.Service,
			Operator: record.Creation.Operator,
		}
	case RecordAction:
		if record.Action == nil {
			return nil, fmt.Errorf("action record is missing its content")
		}
		dto.Action = &actionDTO{
			IncidentID:      record.Action.Request.IncidentID,
			ActionID:        record.Action.Request.ActionID,
			Operator:        record.Action.Request.Operator,
			ExpectedVersion: record.Action.Request.ExpectedVersion,
			Type:            record.Action.Request.Type,
			Content:         record.Action.Request.Content,
		}
	default:
		return nil, fmt.Errorf("unknown record kind %q", record.Kind)
	}
	return json.Marshal(dto)
}

// DecodeRecord strictly decodes one record frame and re-validates it, so a
// frame containing illegal data is rejected as corruption at startup.
func DecodeRecord(data []byte) (Record, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	var dto recordDTO
	if err := dec.Decode(&dto); err != nil {
		return Record{}, fmt.Errorf("decode incident record: %w", err)
	}
	var extra json.RawMessage
	if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return Record{}, fmt.Errorf("decode incident record: unexpected trailing data")
		}
		return Record{}, fmt.Errorf("decode incident record: %w", err)
	}
	if dto.At.IsZero() {
		return Record{}, fmt.Errorf("incident record is missing its timestamp")
	}

	record := Record{Kind: dto.Kind, At: dto.At.UTC()}
	switch dto.Kind {
	case RecordCreation:
		if dto.Creation == nil || dto.Action != nil {
			return Record{}, fmt.Errorf("creation record has the wrong shape")
		}
		creation := Creation{
			ID:       dto.Creation.ID,
			Title:    dto.Creation.Title,
			Service:  dto.Creation.Service,
			Operator: dto.Creation.Operator,
		}
		if _, err := NormalizeCreation(creation); err != nil {
			return Record{}, err
		}
		record.Creation = &creation
	case RecordAction:
		if dto.Action == nil || dto.Creation != nil {
			return Record{}, fmt.Errorf("action record has the wrong shape")
		}
		req := Request{
			IncidentID:      dto.Action.IncidentID,
			ActionID:        dto.Action.ActionID,
			Operator:        dto.Action.Operator,
			ExpectedVersion: dto.Action.ExpectedVersion,
			Type:            dto.Action.Type,
			Content:         dto.Action.Content,
		}
		if _, err := NormalizeRequest(req); err != nil {
			return Record{}, err
		}
		record.Action = &StoredAction{Request: req, At: dto.At.UTC()}
	default:
		return Record{}, fmt.Errorf("unknown record kind %q", dto.Kind)
	}
	return record, nil
}

package logfile

import (
	"fmt"

	"github.com/cocosolocoder/signalroom/internal/incidents"
)

// incidentLogName is the append-only record log for incidents. It sits next
// to events.log in the locked data directory and uses the same
// length-prefixed, CRC-checked frame layout, so the durability and recovery
// rules are identical: fsync before acknowledging, trim only a torn tail,
// and refuse to start on any other corruption.
const incidentLogName = "incidents.log"

// IncidentLog is the concurrency-safe durable writer for incident records.
// It is independent from the event log: an incident write failure poisons
// only incident handling, exactly as an event write failure poisons only
// event ingestion.
type IncidentLog struct {
	*frameLog
}

// OpenIncidentLog opens (creating if absent) the incident log inside an
// already-locked data directory, replays its records, and truncates at most
// one incomplete trailing frame. A corrupt frame in the middle, or a
// complete frame containing illegal data, is fatal and leaves the file
// untouched. Call it only after Open has acquired the directory lock.
func OpenIncidentLog(dir string) (*IncidentLog, []incidents.Record, error) {
	return OpenIncidentLogChecked(dir, nil)
}

// OpenIncidentLogChecked is OpenIncidentLog with an additional validation of
// the recovered records. The check runs after replay and before any torn
// tail is truncated, so a rejection — for example a complete record whose
// handover breaks the personnel rules — is fatal and leaves the file
// byte-for-byte intact, incomplete trailing frame included. Only a log that
// passes the check may have its one incomplete trailing frame dropped.
func OpenIncidentLogChecked(dir string, check func(records []incidents.Record) error) (*IncidentLog, []incidents.Record, error) {
	if dir == "" {
		return nil, nil, fmt.Errorf("data directory is required")
	}
	base, records, err := openFrameLog(dir, incidentLogName, "incident", "incident record", incidents.DecodeRecord, check)
	if err != nil {
		return nil, nil, err
	}
	return &IncidentLog{frameLog: base}, records, nil
}

// AppendRecord durably writes one record: the frame is written and fsynced
// before the call returns. Any write or sync failure poisons the log so that
// this call and every later one fail until restart.
func (l *IncidentLog) AppendRecord(record incidents.Record) error {
	payload, err := incidents.MarshalRecord(record)
	if err != nil {
		return fmt.Errorf("encode incident record: %w", err)
	}
	return l.appendFrame(payload)
}

