757			t.Fatalf("preview differs across restart:\n%s\n%s", before, after)
758		}
759	
760		// Replaying an identical batch after restart leaves the preview unchanged.
761		postEvents(t, p2, `{"events":[`+
762			`{"id":"e1","service":"gateway","severity":"critical","message":"m","at":"2026-10-01T10:00:05Z","labels":{"env":"prod"}},`+
763			`{"id":"e2","service":"gateway","severity":"critical","message":"m","at":"2026-10-01T10:01:05Z","labels":{"env":"prod"}},`+
764			`{"id":"e3","service":"api","severity":"info","message":"m","at":"2026-10-01T10:00:05Z"}]}`)
765		_, replayed := httpDo(t, http.MethodPost, "http://"+p2.addr+"/alerts/preview", body)
766		if !bytes.Equal(before, replayed) {
767			t.Fatalf("replaying events changed the preview:\n%s\n%s", before, replayed)
768		}
769		p2.signal(t, syscall.SIGTERM)
770		p2.waitExit(t, 0)
771	}
772	
773	func TestServePageSnapshotStableAcrossRestart(t *testing.T) {
774		dataDir := t.TempDir()
775		p := startServer(t, dataDir)
776		postEvents(t, p, `{"events":[
777			{"id":"e1","service":"s","severity":"info","message":"m","at":"2026-10-01T09:00:00Z"},
778			{"id":"e2","service":"s","severity":"info","message":"m","at":"2026-10-01T09:02:00Z"}
779		]}`)
780	
781		// First page, limit 1.
782		_, out := pageGet(t, p, "?limit=1")
783		if out.NextCursor == nil {
784			t.Fatal("expected a next_cursor")
785		}
786	
787		// Restart, then ingest a new event with an earlier time.
788		p.signal(t, syscall.SIGKILL)
789		p.waitExit(t, -1)
790		waitTCPPortClosed(t, p.addr)
791		p2 := startServer(t, dataDir)
792		postEvents(t, p2, `{"events":[{"id":"e0","service":"s","severity":"info","message":"m","at":"2026-10-01T08:00:00Z"}]}`)
793	
794		// The old cursor must continue the old snapshot, not see e0.
795		_, out = pageGet(t, p2, "?limit=1&cursor="+*out.NextCursor)
796		if len(out.Events) != 1 || out.Events[0]["id"] != "e2" {
797			t.Fatalf("old cursor must not see post-restart event: %v", out.Events)
798		}
799		p2.signal(t, syscall.SIGTERM)
