	}
	// The save format HTML-escapes a less-than character to the six-byte
	// sequence <, so a durable run of the rejected note would show up as
	// a long stretch of that sequence.
	if strings.Count(string(onDisk), strings.Repeat(`<`, 1000)) != 0 {
